    const double sin_clat = std::sin(clat);
    const double w = std::sqrt(1.0 - wgs84::e2 * sin_clat * sin_clat);
    const double N = wgs84::a / w;
    const double M = wgs84::a * (1.0 - wgs84::e2) / (w * w * w);
    const double dlat = 1.58 / M; // ~1.58m North/South
    const double dlon = 1.58 / (N * std::cos(clat)); // ~1.58m East/West

    std::vector<LatLon> poly = {
        {clat - dlat, clon - dlon}, // SW
        {clat + dlat, clon - dlon}, // NW
        {clat + dlat, clon + dlon}, // NE
        {clat - dlat, clon + dlon}  // SE
    };

    auto metrics = polygon::compute(poly);

    std::cout << std::fixed << std::setprecision(10);
    std::cout << "=== WGS84 Geodesic Polygon Metrics (Svalbard 78.22N) ===\n";
    std::cout << "Vertices: " << poly.size() << "\n";
    std::cout << "Area:            " << metrics.area_m2 << " m^2\n";
    std::cout << "Perimeter:       " << metrics.perimeter_m << " m\n";
    std::cout << "Authalic Radius: " << wgs84::R_A << " m\n";
    std::cout << "\nPer-Edge Geodesics (Vincenty Inverse):\n";
    for (size_t i = 0; i < metrics.edges.size(); ++i) {
        const auto& e = metrics.edges[i];
        std::cout << "  Edge " << i << ": s=" << e.s << " m, "
