/* ============================================================================
 * Platform & Architecture Abstraction
 * ============================================================================
 * ARMv8-A (AArch64) Bare-Metal MMIO Access Primitives.
 * Assumes Device-nGnRnE memory type (standard for peripherals).
 * Requires explicit Data Memory Barriers (DMB) for ordering.
 * ============================================================================ */

#if defined(__aarch64__)
    #define ARCH_ARM64 1
#elif defined(__arm__)
    #define ARCH_ARM32 1
#else
    #error "Unsupported architecture: ARMv8-A (AArch64) required."
#endif

/* Compiler Barrier: Prevents compiler reordering. */
static inline void compiler_barrier(void) {
    __asm__ volatile ("" ::: "memory");
}

/* Hardware Memory Barrier: DMB ISH (Inner Shareable Domain). */
static inline void dmb_ish(void) {
#if ARCH_ARM64
    __asm__ volatile ("dmb ish" ::: "memory");
#elif ARCH_ARM32
    __asm__ volatile ("dmb ish" ::: "memory");
#endif
}

/* Yield Hint: Polite busy-wait (WFE/YIELD). */
static inline void cpu_yield(void) {
#if ARCH_ARM64
    __asm__ volatile ("yield" ::: "memory");
#elif ARCH_ARM32
    __asm__ volatile ("wfe" ::: "memory");
#endif
}

