periph_status_t peripheral_init(uint32_t ctrl_init_val, uint32_t irq_mask_init) {
    /* 1. Hard Reset via CTRL (assuming bit 0 is RESET, self-clearing) */
    ctrl_write(BIT_MASK(0)); /* Assert Reset */
    mmio_iso_barrier();      /* Ensure reset instruction retires */
    /* Poll for reset clear (assuming HW clears bit 0 when done) */
    for (volatile int i = 0; i < 1000; ++i) {
        if ((ctrl_read() & BIT_MASK(0)) == 0U) break;
