    irq_mask_write(irq_mask_init);

    /* 4. Write Control Register (Enable, Mode, etc.) */
    ctrl_write(ctrl_init_val);

    return PERIPH_OK;
}

/* Blocking Polled Transfer (Example Usage Pattern) */
periph_status_t peripheral_transfer_polled(const uint32_t *tx_buf, uint32_t *rx_buf, size_t word_count) {
    if (word_count == 0) return PERIPH_OK;

    /* Check TX FIFO Ready (assume STATUS bit 1 = TX_READY) */
    const uint32_t TX_READY = BIT_MASK(1);
    const uint32_t RX_VALID = BIT_MASK(2);
    const uint32_t ERR_FLAG = BIT_MASK(31);

    size_t tx_idx = 0;
    size_t rx_idx = 0;

    while (tx_idx < word_count || rx_idx < word_count) {
        uint32_t status = status_read();

        if (status & ERR_FLAG) {
            status_clear_bits(ERR_FLAG);
            return PERIPH_ERR_BUSY; /* Or specific error code */
        }

        /* Handle TX Burst if possible */
        if (tx_idx < word_count && (status & TX_READY)) {
            size_t remaining = word_count - tx_idx;
            size_t burst_len = (remaining >= 16) ? 16 : remaining; /* Max burst 16 words */

            /* Align check for burst */
            if (burst_len == 16 && (((uintptr_t)(tx_buf + tx_idx) & 63U) == 0U)) {
                if (!data_write_burst(tx_buf + tx_idx, 16)) return PERIPH_ERR_ALIGNMENT;
                tx_idx += 16;
            } else {
                /* Single word fallback */
                data_write(tx_buf[tx_idx++]);
            }
        }

        /* Handle RX Burst if possible */
        if (rx_idx < word_count && (status & RX_VALID)) {
            size_t remaining = word_count - rx_idx;
            size_t burst_len = (remaining >= 16) ? 16 : remaining;

            if (burst_len == 16 && (((uintptr_t)(rx_buf + rx_idx) & 63U) == 0U)) {
                if (!data_read_burst(rx_buf + rx_idx, 16)) return PERIPH_ERR_ALIGNMENT;
                rx_idx += 16;
            } else {
                rx_buf[rx_idx++] = data_read();
            }
        }

        /* Prevent busy-spin lockup if hardware stalls (architectural timeout) */
        __builtin_arm_nop(); /* Yield / WFE hint could go here */
    }

    return PERIPH_OK;
}

