void warpReduceXor(T vals[WARP_SIZE], Op op) {
    for (int offset = WARP_SIZE/2; offset > 0; offset >>= 1) {
        T temp[WARP_SIZE];
        for (int i = 0; i < WARP_SIZE; ++i) {
            temp[i] = op(vals[i], vals[i ^ offset]);
