    MediaReference() = default;
    MediaReference(std::string n, Rational s, Rational d, int64_t w, int64_t h, int64_t c)
        : name(std::move(n)), available_range_start(s), available_range_duration(d), width(w), height(h), channels(c) {}
};

struct Clip {
