namespace wgs84 {
    constexpr double a       = 6378137.0;                 // Semi-major axis (m)
    constexpr double f       = 1.0 / 298.257223563;       // Flattening
    constexpr double e2      = f * (2.0 - f);             // Eccentricity squared
    constexpr double ep2     = e2 / (1.0 - e2);           // Second eccentricity squared
    constexpr double b       = a * (1.0 - f);             // Semi-minor axis
    constexpr double pi      = 3.14159265358979323846264338327950288419716939937510;
    constexpr double deg2rad = pi / 180.0;

    // Authalic Radius (Sphere of equal surface area)
    constexpr double R_auth  = a * std::sqrt(1.0 - e2 * (1.0/3.0 + e2*(1.0/5.0 + e2*(1.0/7.0 + e2/9.0)))); // Series approx for R_auth
    // Exact Authalic Radius:
    // R_auth^2 = 0.5 * a^2 * (1 + (1-e^2)/e * atanh(e)) ... wait, standard formula:
    // R_auth = a * sqrt( (1 - e^2/2 - ...) ) -> Use exact closed form:
