{
    peripheral_init();

    peripheral_ctrl_set(BIT(0));          // enable peripheral
    peripheral_data_write(0xA5A5A5A5U);   // send payload
    uint32_t status = peripheral_status_get();
    peripheral_status_clear(status);     // clear all pending flags

    peripheral_irqmask_enable(BIT(2));    // enable IRQ line 2
    return 0;
}
*/

