void test_rational_time() {
    RationalTime a = RationalTime::from_frames(24, 24); // 1s
    RationalTime b = RationalTime::from_frames(30, 30); // 1s
    assert_equal(a, b, "Rate equality 24/24 vs 30/30");

    RationalTime c = a.rescaled_to(48000);
    assert_equal(c, RationalTime::from_frames(48000, 48000), "Rescale 1s to 48k");

    RationalTime d = RationalTime::from_frames(1, 24); // 1 frame
    RationalTime e = d.rescaled_to(30);
    // 1/24 * 30 = 1.25 -> rounded to 1 frame at 30fps? 
    // Nearest: 1.25 -> 1. 
    // Wait: (1 * 30 + 12) / 24 = 42/24 = 1. 
    assert_equal(e, RationalTime::from_frames(1, 30), "Rescale 1 frame 24->30 (round)");

    // Overflow check
    RationalTime huge = RationalTime::from_frames(std::numeric_limits<int64_t>::max() / 2, 1);
    RationalTime huge2 = huge.rescaled_to(1000); // Should not crash/UB
    assert(huge2.rate() == 1000);
}

