    double signed_area_spherical_fan() const {
        const size_t n = vertices_aut_.size();
        if (n < 3) return 0.0;
        double sum = 0.0;
        const auto& v0 = vertices_aut_[0];
        for (size_t i = 1; i + 1 < n; ++i) {
            const double az1 = azimuth(v0, vertices_aut_[i]);
            const double az2 = azimuth(v0, vertices_aut_[i+1]);
            double diff = az2 - az1;
            if (diff > M_PI) diff -= 2*M_PI;
            if (diff < -M_PI) diff += 2*M_PI;
            sum += diff; // Sum of angles at v0
        }
        return sum; // >0 CCW
