    for (int i = 0; i < WARP_SIZE; ++i)
        max_ulp = std::max(max_ulp, ulp_distance(extreme_out[i], extreme_ref[i]));
    printf("Extreme test: max ULP error = %d\n", max_ulp);

    // Test 3: Uniform large values (should yield 1/32 each)
    half uniform[WARP_SIZE];
    for (int i = 0; i < WARP_SIZE; ++i) uniform[i] = float_to_half(1000.0f);
